#include <stdio.h>
#include <string.h>

void function(const char *input) {
    char buffer[10];
    strcpy(buffer, input);
    printf("Data copied: %s\n", buffer);
}

int main() {
    char large_string[30] = "This is a very long string!";
    function(large_string);
    return 0;
}
