'$searchTerm'";
$result = $conn->query($sql);

if ($result->num_rows > 0) {
    // Hiển thị thông tin sản phẩm
    while($row = $result->fetch_assoc()) {
        echo "Product Name: " . $row["product_name"]. "<br>";
